select r.recommendation_date,r.id,s.stock_code,s.market,r.rank_no,r.recommendation_score,r.volume_ratio,r.daily_trading_value,r.five_minute_change_rate,r.feature_snapshot::jsonb->>'tradeStrength' trade_strength,r.feature_snapshot::jsonb->>'vwapDistanceRate' vwap_distance,r.feature_snapshot::jsonb->>'dayHighDistanceRate' high_distance,r.feature_snapshot::jsonb->>'turnoverRatio' turnover,p.close_return_rate,p.max_return_rate,p.max_drawdown_rate from closing_recommendation r join stock s on s.id=r.stock_id join overnight_performance p on p.closing_recommendation_id=r.id where p.status='COMPLETED' order by r.id;
select market_session_date,count(*) n,count(*) filter(where (feature_snapshot::jsonb->>'occurredAt')::timestamptz>detected_at) feature_after_detection,max(extract(epoch from (feature_snapshot::jsonb->>'occurredAt')::timestamptz-detected_at)) max_seconds from scanner_detection group by 1 order by 1;
select r.id,r.recommendation_date,d.detected_at,d.received_at,(r.feature_snapshot::jsonb->>'occurredAt')::timestamptz feature_at,a.evaluated_as_of,a.completed_at from closing_recommendation r join scanner_detection d on d.id=r.source_detection_id join closing_recommendation_run a on a.id=r.run_id where r.id=117;
select r.id,c.start_time,c.open,c.close,c.source,c.created_at,c.updated_at from closing_recommendation r join stock_candle c on c.stock_id=r.stock_id and c.timeframe='5M' and (c.start_time at time zone 'Asia/Seoul')::date=r.recommendation_date and (c.start_time at time zone 'Asia/Seoul')::time in (time '14:50',time '14:55',time '15:05',time '15:30') where r.id=117 order by c.start_time;
select a.id,e->>'stockCode' code,e->>'decisionReason' reason,e->'dataReadiness' readiness from closing_recommendation_run a cross join lateral jsonb_array_elements(coalesce(a.response_snapshot::jsonb->'evaluations','[]')) e where a.id in (27,30) and e->>'stockCode'='042700';
